import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        // Convert n to base-k digits
        int[] baseDigits = new int[64]; // maximum size for long in base conversion
        int size = 0;
        while (n > 0) {
            baseDigits[size++] = (int)(n % k);
            n /= k;
        }

        // Initialize matrix
        long[][] mat = new long[k + 1][k + 1];
        for (int j = 0; j <= k; j++) {
            mat[0][j] = 1;
            mat[j][j] = 1;
        }

        // Matrix multiplication
        java.util.function.BiFunction<long[][], long[][], long[][]> matMult = (A, B) -> {
            long[][] res = new long[k + 1][k + 1];
            for (int i = 0; i <= k; i++) {
                for (int j = 0; j <= k; j++) {
                    long sumRes = 0;
                    for (int l = 0; l <= k; l++) {
                        sumRes += A[i][l] * B[l][j];
                    }
                    res[i][j] = sumRes % 1000000007;
                }
            }
            return res;
        };

        // Matrix exponentiation
        java.util.function.BiFunction<long[][], Long, long[][]> matPow = (base, exp) -> {
            long[][] result = new long[k + 1][k + 1];
            for (int i = 0; i <= k; i++) {
                result[i][i] = 1;
            }
            long e = exp;
            long[][] baseCopy = new long[k + 1][k + 1];
            for (int i = 0; i <= k; i++) {
                System.arraycopy(base[i], 0, baseCopy[i], 0, k + 1);
            }
            while (e > 0) {
                if ((e & 1) == 1) {
                    result = matMult.apply(result, baseCopy);
                }
                baseCopy = matMult.apply(baseCopy, baseCopy);
                e >>= 1;
            }
            return result;
        };

        long[][] A = new long[k + 1][k + 1];
        for (int i = 0; i <= k; i++) {
            System.arraycopy(mat[i], 0, A[i], 0, k + 1);
        }

        long sum = 0;
        for (int i = size - 1; i >= 0; i--) {
            int digit = baseDigits[i];
            for (int j = 0; j < digit; j++) {
                long[][] temp = matPow.apply(A, (long)((j + sum) % k));
                for (int x = 0; x <= k; x++) {
                    for (int y = 0; y <= k; y++) {
                        mat[x][y] = (mat[x][y] + temp[x][y]) % 1000000007;
                    }
                }
            }
            sum = (sum + digit) % k;
        }

        long result = 0;
        for (int i = 0; i <= k; i++) {
            result = (result + mat[i][k]) % 1000000007;
        }

        System.out.println(result);
        sc.close();
    }
}
